import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { ChevronLeft, Check, Globe, Languages } from 'lucide-react'

export default function Language() {
    const navigate = useNavigate()
    const [selectedLanguage, setSelectedLanguage] = useState(() => {
        return localStorage.getItem('language') || 'en'
    })

    useEffect(() => {
        localStorage.setItem('language', selectedLanguage)
        // You can add i18n logic here later
    }, [selectedLanguage])

    const languages = [
        { 
            id: 'en', 
            name: 'English', 
            nativeName: 'English',
            flag: '🇬🇧',
            code: 'en'
        },
        { 
            id: 'es', 
            name: 'Spanish', 
            nativeName: 'Español',
            flag: '🇪🇸',
            code: 'es'
        },
        { 
            id: 'fr', 
            name: 'French', 
            nativeName: 'Français',
            flag: '🇫🇷',
            code: 'fr'
        },
        { 
            id: 'de', 
            name: 'German', 
            nativeName: 'Deutsch',
            flag: '🇩🇪',
            code: 'de'
        },
        { 
            id: 'it', 
            name: 'Italian', 
            nativeName: 'Italiano',
            flag: '🇮🇹',
            code: 'it'
        },
        { 
            id: 'pt', 
            name: 'Portuguese', 
            nativeName: 'Português',
            flag: '🇵🇹',
            code: 'pt'
        },
        { 
            id: 'nl', 
            name: 'Dutch', 
            nativeName: 'Nederlands',
            flag: '🇳🇱',
            code: 'nl'
        },
        { 
            id: 'af', 
            name: 'Afrikaans', 
            nativeName: 'Afrikaans',
            flag: '🇿🇦',
            code: 'af'
        }
    ]

    return (
        <div className="min-h-screen bg-gray-50 px-4 py-6 pb-20">
            <div className="flex items-center gap-3 mb-6">
                <button 
                    onClick={() => navigate(-1)}
                    className="p-2 hover:bg-gray-200 rounded-lg transition"
                >
                    <ChevronLeft size={24} className="text-gray-700" />
                </button>
                <h1 className="text-2xl font-bold text-gray-800">Language</h1>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="p-4 border-b border-gray-100 flex items-center gap-2">
                    <Globe size={18} className="text-gray-400" />
                    <p className="text-sm text-gray-500">Select your preferred language</p>
                </div>
                {languages.map((lang) => {
                    const isSelected = selectedLanguage === lang.id
                    return (
                        <button
                            key={lang.id}
                            onClick={() => setSelectedLanguage(lang.id)}
                            className={`w-full flex items-center justify-between px-4 py-4 hover:bg-gray-50 transition border-b border-gray-100 last:border-0 ${
                                isSelected ? 'bg-gray-50' : ''
                            }`}
                        >
                            <div className="flex items-center gap-3">
                                <span className="text-2xl">{lang.flag}</span>
                                <div className="text-left">
                                    <span className="font-medium text-gray-800">{lang.name}</span>
                                    <p className="text-xs text-gray-400">{lang.nativeName}</p>
                                </div>
                            </div>
                            {isSelected && (
                                <Check size={20} className="text-gray-800" />
                            )}
                        </button>
                    )
                })}
            </div>

            <div className="mt-6 bg-yellow-50 rounded-xl p-4 border border-yellow-200">
                <p className="text-sm text-yellow-700">
                    🌐 Language support is coming soon. Currently only English is fully supported.
                </p>
            </div>
        </div>
    )
}
